  {"id":3091,"chap":"LudicrousVoltage","chapcn":"第6阶-荒唐电压(LuV)","chapi":9,"name":"太阳聚变","pre":[1212],"desc":"批量生产阳光化合物的替代方案。","items":[["gregtech:gt.metaitem.99",318,1]],"rule":{"pre":[1212],"preLogic":"AND","taskLogic":"AND","groups":[{"id":"0:10","type":"retrieval","ignoreNBT":true,"partialNBT":true,"optional":true,"items":[{"k":"gregtech:gt.metaitem.01@31004","n":1},{"k":"gregtech:gt.metaitem.99@811","n":1}]},{"id":"1:10","type":"retrieval","ignoreNBT":true,"partialNBT":true,"items":[{"k":"gregtech:gt.metaitem.99@318","n":1}]}],"resolved":true}},
  {"id":950010,"chap":"LudicrousVoltage","chapcn":"第6阶-荒唐电压(LuV)","chapi":9,"name":"贫瘠下界废水","pre":[950019],"desc":"一旦你收集到足够的泡沫，就可以通过真空干燥炉处理它以获得许多有用的资源。最重要的是，在这里我们可以提取出贫瘠下界废水；这是下界合金生产线中非常宝贵的一种流体。","items":[["gregtech:gt.metaitem.01",30123,16]],"rule":{"pre":[950019],"preLogic":"AND","taskLogic":"AND","groups":[{"id":"0:10","type":"retrieval","ignoreNBT":true,"partialNBT":true,"optional":true,"items":[{"k":"miscutils:FrothNetherrackflotation@0","n":3}]},{"id":"1:10","type":"retrieval","ignoreNBT":true,"partialNBT":true,"items":[{"k":"gregtech:gt.metaitem.01@30123","n":16}]}],"resolved":true}},
  {"id":950011,"chap":"LudicrousVoltage","chapcn":"第6阶-荒唐电压(LuV)","chapi":9,"name":"易碎的下界合金碎片","pre":[950010,950022],"desc":"你已经非常接近了，只剩下最后几步。\n\n现在你已经获得了下界合金碎片种子，可以将它们与贫瘠下界废水在化学浸洗机中结合,有50%%的几率获得3个脆弱的下界合金碎片。作为奖励，还有50%%的几率返还你的下界合金碎片种子，以便再次运行该配方。\n\n别担心，这是最后一个基于几率的下界合金配方。","items":[["gregtech:gt.metaitem.03",32244,1]],"rule":{"pre":[950010,950022],"preLogic":"AND","taskLogic":"AND","groups":[{"id":"0:10","type":"retrieval","ignoreNBT":true,"partialNBT":true,"optional":true,"items":[{"k":"gregtech:gt.metaitem.03@32243","n":1},{"k":"gregtech:gt.metaitem.01@30123","n":16}]},{"id":"1:10","type":"retrieval","ignoreNBT":true,"partialNBT":true,"items":[{"k":"gregtech:gt.metaitem.03@32244","n":1}]}],"resolved":true}},
  {"id":950012,"chap":"LudicrousVoltage","chapcn":"第6阶-荒唐电压(LuV)","chapi":9,"name":"下界合金纳米颗粒","pre":[950011],"desc":"下界合金纳米颗粒可通过研磨你才刚得到的的脆弱的下界合金碎片获得。\n\n是不是觉得有点太简单了？","items":[["gregtech:gt.metaitem.03",32245,1]],"rule":{"pre":[950011],"preLogic":"AND","taskLogic":"AND","groups":[{"id":"0:10","type":"retrieval","ignoreNBT":true,"partialNBT":true,"optional":true,"items":[{"k":"gregtech:gt.metaitem.03@32244","n":1}]},{"id":"1:10","type":"retrieval","ignoreNBT":true,"partialNBT":true,"items":[{"k":"gregtech:gt.metaitem.03@32245","n":1}]}],"resolved":true}},
  {"id":950013,"chap":"LudicrousVoltage","chapcn":"第6阶-荒唐电压(LuV)","chapi":9,"name":"地狱金属","pre":[950011],"desc":"一般的下界合金纳米颗粒本身没有足够的密度来压缩成下界合金……它需要一些更强的，甚至带些魔力的粘合剂。\n\n地狱金属就是一个理想的选择，你可以选择使用电解机或者注魔来生产它。\n\n注魔配方相对来说更加实惠，但你需要坚实的魔法基础来使用它。","items":[["gregtech:gt.blockmetal9",12,1]],"rule":{"pre":[950011],"preLogic":"AND","taskLogic":"AND","groups":[{"id":"0:10","type":"retrieval","ignoreNBT":true,"partialNBT":true,"optional":true,"items":[{"k":"bartworks:bw.werkstoffblocks.01@78","n":1},{"k":"ThaumicTinkerer:kamiResource@6","n":2},{"k":"gregtech:gt.metaitem.01@11330","n":2}]},{"id":"1:10","type":"retrieval","ignoreNBT":true,"partialNBT":true,"optional":true,"items":[{"k":"bartworks:bw.werkstoffblocks.01@78","n":1},{"k":"ThaumicTinkerer:kamiResource@6","n":8},{"k":"gregtech:gt.metaitem.01@2541","n":8},{"k":"gregtech:gt.metaitem.99@330","n":8}]},{"id":"2:10","type":"retrieval","ignoreNBT":true,"partialNBT":true,"items":[{"k":"gregtech:gt.blockmetal9@12","n":1}]}],"resolved":true}},
  {"id":950019,"chap":"LudicrousVoltage","chapcn":"第6阶-荒唐电压(LuV)","chapi":9,"name":"地狱岩泡沫","pre":[950030,950020],"desc":"将研磨产物与邪恶原油在浮选机中混合，你就可以得到地狱岩泡沫。\n\n你可能需要保证它的稳定供应。","items":[["miscutils:FrothNetherrackflotation",0,1]],"rule":{"pre":[950030,950020],"preLogic":"AND","taskLogic":"AND","groups":[{"id":"0:10","type":"retrieval","ignoreNBT":true,"partialNBT":true,"optional":true,"items":[{"k":"miscutils:milledNetherrack@0","n":256},{"k":"gregtech:gt.metaitem.01@30122","n":8}]},{"id":"1:10","type":"retrieval","ignoreNBT":true,"partialNBT":true,"items":[{"k":"miscutils:FrothNetherrackflotation@0","n":1}]}],"resolved":true}},
  {"id":950020,"chap":"LudicrousVoltage","chapcn":"第6阶-荒唐电压(LuV)","chapi":9,"name":"邪恶原油","pre":[950031,950061],"desc":"通过在石油裂化机中使用净化水，你可以将上一步得到的邪恶气体转化为邪恶原油。\n\n如果你已经搭建了二级净化水产线，那么你可以使用另一个配方，它能用少得多的水、短得多的时间生成多得多的原油。","items":[["gregtech:gt.metaitem.01",30122,12]],"rule":{"pre":[950031,950061],"preLogic":"AND","taskLogic":"AND","groups":[{"id":"0:10","type":"retrieval","ignoreNBT":true,"partialNBT":true,"optional":true,"items":[{"k":"gregtech:gt.metaitem.01@30555","n":1},{"k":"gregtech:gt.metaitem.01@30120","n":16}]},{"id":"1:10","type":"retrieval","ignoreNBT":true,"partialNBT":true,"optional":true,"items":[{"k":"gregtech:gt.metaitem.01@30554","n":4},{"k":"gregtech:gt.metaitem.01@30120","n":16}]},{"id":"2:10","type":"retrieval","ignoreNBT":true,"partialNBT":true,"items":[{"k":"gregtech:gt.metaitem.01@30122","n":12}]}],"resolved":true}},
  {"id":950021,"chap":"LudicrousVoltage","chapcn":"第6阶-荒唐电压(LuV)","chapi":9,"name":"富集下界废水","pre":[950031,950010],"desc":"其中一种使用贫瘠下界废水的方法，是将其与之前获得的地狱泥在搅拌机中混合，以合成富集下界废水。\n\n我们将在下一步中使用富集下界废水，它在相当长的一段时间里都会很重要。不过当你到达UHV阶段时，它最终会在产线中失去必要性。","items":[["gregtech:gt.metaitem.01",30124,16]],"rule":{"pre":[950031,950010],"preLogic":"AND","taskLogic":"AND","groups":[{"id":"0:10","type":"retrieval","ignoreNBT":true,"partialNBT":true,"optional":true,"items":[{"k":"gregtech:gt.metaitem.03@32242","n":32},{"k":"gregtech:gt.metaitem.01@30123","n":16}]},{"id":"1:10","type":"retrieval","ignoreNBT":true,"partialNBT":true,"items":[{"k":"gregtech:gt.metaitem.01@30124","n":16}]}],"resolved":true}},
  {"id":950022,"chap":"LudicrousVoltage","chapcn":"第6阶-荒唐电压(LuV)","chapi":9,"name":"下界合金碎片种子","pre":[950032,950021],"desc":"终于，我们可以开始利用一些下界合金碎片了！\n\n将热下界合金碎片与一些富集地狱废水在一个高压釜中合成，有10%%的几率获得一个下界合金碎片种子。\n\n需要注意的是，如之前所提到的，下界合金碎片在这个配方中会被循环利用，所以真正的消耗只是富集下界废水。鉴于概率较低，你需要让这个配方尽可能频繁地运行。","items":[["gregtech:gt.metaitem.03",32243,1]],"rule":{"pre":[950032,950021],"preLogic":"AND","taskLogic":"AND","groups":[{"id":"0:10","type":"retrieval","ignoreNBT":true,"partialNBT":true,"optional":true,"items":[{"k":"gregtech:gt.metaitem.03@32247","n":2},{"k":"gregtech:gt.metaitem.01@30124","n":2}]},{"id":"1:10","type":"retrieval","ignoreNBT":true,"partialNBT":true,"items":[{"k":"gregtech:gt.metaitem.03@32243","n":1}]}],"resolved":true}},
  {"id":950023,"chap":"LudicrousVoltage","chapcn":"第6阶-荒唐电压(LuV)","chapi":9,"name":"强键合下界合金纳米颗粒","pre":[950013,950012,2607],"desc":"终于到了……制作下界合金材料前的最后一味原料。\n\n通过在工业高炉里结合下界合金纳米颗粒和地狱金属，你可以获得强键合下界合金纳米颗粒。作为给养蜂人们的一个福利，使用下界合金蜂后搭建的蜂窝，你可以得到2倍产物。\n\n它们并不只是致密下界合金板（用于搭建聚变反应堆）所需的主要前置材料，也是制作其他下界合金部件（在你制作了其中一个后）的前置材料。所以一定要生产尽可能多的下界合金纳米颗粒，并将它们囤积起来。\n\n记住，这个配方需要硅岩线圈！","items":[["gregtech:gt.metaitem.03",32246,1]],"rule":{"pre":[950013,950012,2607],"preLogic":"AND","taskLogic":"AND","groups":[{"id":"0:10","type":"retrieval","ignoreNBT":true,"partialNBT":true,"optional":true,"items":[{"k":"gregtech:gt.metaitem.03@32245","n":1},{"k":"gregtech:gt.metaitem.99@125","n":1}]},{"id":"1:10","type":"retrieval","ignoreNBT":true,"partialNBT":true,"optional":true,"items":[{"k":"gregtech:gt.metaitem.03@32245","n":1},{"k":"gregtech:gt.comb@169","n":32},{"k":"gregtech:gt.metaitem.99@125","n":1}]},{"id":"2:10","type":"retrieval","ignoreNBT":true,"partialNBT":true,"items":[{"k":"gregtech:gt.metaitem.03@32246","n":1}]}],"resolved":true}},
  {"id":2760,"name":"这到底是啥?","chap":"MultiblockGoals","chapcn":"多方块结构","chapi":22,"pre":[1493],"desc":"它不单是台多方块脱水机，也是台真空干燥炉，不过真空干燥炉没有单方块机器。它应该配合艾萨研磨机和工业浮选机这两台多方块机器，用于矿物研磨处理，这是一套进阶矿物处理系统，它需要一系列的配套机器，不过对于支持的矿石也可以提供许多新产出。\n\n[note]这台多方块机器现在可以在LuV阶段制造了！[/note]","items":[],"rule":{"pre":[1493],"preLogic":"AND","taskLogic":"AND","groups":[{"id":"0:10","type":"retrieval","ignoreNBT":true,"partialNBT":true,"items":[{"k":"gregtech:gt.blockmachines@995","n":1},{"k":"miscutils:gtplusplus.blockcasings.4@10","n":1}]}],"resolved":true}},
  {"id":3144,"name":"铟太多了?","chap":"MultiblockGoals","chapcn":"多方块结构","chapi":22,"pre":[2760],"desc":"研磨处理线是另一种可选的产铟方式，为LuV及以上阶段的玩家设计。它不会无理由地销毁铝和方铅，并且使你可以高效地从闪锌中提取出铟。而代价就是相关机器和基础设施的投入。","items":[],"rule":{"pre":[2760],"preLogic":"AND","taskLogic":"AND","groups":[{"id":"0:10","type":"retrieval","ignoreNBT":true,"partialNBT":true,"items":[{"k":"gregtech:gt.blockmachines@31027","n":1}]},{"id":"1:10","type":"retrieval","ignoreNBT":true,"partialNBT":true,"items":[{"k":"gregtech:gt.blockmachines@31028","n":1}]}],"resolved":true}},
  {"id":950030,"chap":"LudicrousVoltage","chapcn":"第6阶-荒唐电压(LuV)","chapi":9,"name":"粉碎地狱岩","pre":[3144,950045],"desc":"随着下界合金线到来的是第一处你必须用到艾萨研磨机的地方。你需要用它制作研磨地狱岩。你会用到很多研磨地狱岩，所以应当时刻注意维持你的地狱岩和研磨球产出。\n\n地狱岩的最佳生产方式是在碎石机里使用荧石粉，或者压缩地狱岩粉（你可能在挖矿时搞到了一大堆）。\n\n研磨球的生产有两个选项：\n\n-皂石->更便宜，但只有铝的50%%效率\n-铝->更贵，但比皂石有效两倍","items":[["miscutils:milledNetherrack",0,256]],"rule":{"pre":[3144,950045],"preLogic":"AND","taskLogic":"AND","groups":[{"id":"0:10","type":"retrieval","ignoreNBT":true,"partialNBT":true,"optional":true,"items":[{"k":"minecraft:netherrack@0","n":2048},{"k":"miscutils:item.BasicGenericChemItem@7","n":1,"nbt":{"MillingBall":{"Damage":0,"MaxDamage":100}}}]},{"id":"1:10","type":"retrieval","ignoreNBT":true,"partialNBT":true,"optional":true,"items":[{"k":"minecraft:netherrack@0","n":4096},{"k":"miscutils:item.BasicGenericChemItem@8","n":1,"nbt":{"MillingBall":{"Damage":0,"MaxDamage":50}}}]},{"id":"2:10","type":"retrieval","ignoreNBT":true,"partialNBT":true,"items":[{"k":"miscutils:milledNetherrack@0","n":256}]}],"resolved":true}},
  {"id":950031,"chap":"LudicrousVoltage","chapcn":"第6阶-荒唐电压(LuV)","chapi":9,"name":"邪恶产物","pre":[950046],"desc":"在开始生产半流质下界空气之后，你可以将它通入蒸馏塔来提取其中的“邪恶”产物。在这条产线的后续步骤中你需要使用重地狱泥，而在下一步中你需要使用邪恶气体。\n\n不要丢弃副产物！里面有很多额外资源可以收集。","items":[["gregtech:gt.metaitem.03",32242,8],["gregtech:gt.metaitem.01",30120,8]],"rule":{"pre":[950046],"preLogic":"AND","taskLogic":"AND","groups":[{"id":"0:10","type":"retrieval","ignoreNBT":true,"partialNBT":true,"optional":true,"items":[{"k":"gregtech:gt.metaitem.01@30119","n":100}]},{"id":"1:10","type":"retrieval","ignoreNBT":true,"partialNBT":true,"items":[{"k":"gregtech:gt.metaitem.03@32242","n":8},{"k":"gregtech:gt.metaitem.01@30120","n":8}]}],"resolved":true}},
  {"id":950032,"chap":"LudicrousVoltage","chapcn":"第6阶-荒唐电压(LuV)","chapi":9,"name":"热下界合金碎片","pre":[950047],"desc":"加热下界合金碎片是个很快的低开销过程。只需要将它丢进化学浸洗机并配上一点岩浆就好！\n\n但你应该记着，你会重复加热这些碎片很多很多次。所以极其推荐你获取一个稳定、持续的岩浆来源。","items":[["gregtech:gt.metaitem.03",32247,2]],"rule":{"pre":[950047],"preLogic":"AND","taskLogic":"AND","groups":[{"id":"0:10","type":"retrieval","ignoreNBT":true,"partialNBT":true,"optional":true,"items":[{"k":"etfuturum:netherite_scrap@0","n":2},{"k":"IC2:itemCellEmpty@2","n":1}]},{"id":"1:10","type":"retrieval","ignoreNBT":true,"partialNBT":true,"items":[{"k":"gregtech:gt.metaitem.03@32247","n":2}]}],"resolved":true}},
  {"id":950033,"chap":"LudicrousVoltage","chapcn":"第6阶-荒唐电压(LuV)","chapi":9,"name":"致密下界合金板","pre":[950023],"desc":"当你搞到了36个强键合下界合金纳米颗粒后，你总算可以制作第一个真正的下界合金材料：致密下界合金板。\n\n你需要它来制作Mk1聚变反应堆，并用其生产其余的下界合金材料。","items":[["gregtech:gt.metaitem.01",22132,1]],"rule":{"pre":[950023],"preLogic":"AND","taskLogic":"AND","groups":[{"id":"0:10","type":"retrieval","ignoreNBT":true,"partialNBT":true,"optional":true,"items":[{"k":"gregtech:gt.metaitem.01@22323","n":8},{"k":"gregtech:gt.metaitem.03@32246","n":36},{"k":"miscutils:pyrotheum@0","n":128}]},{"id":"1:10","type":"retrieval","ignoreNBT":true,"partialNBT":true,"items":[{"k":"gregtech:gt.metaitem.01@22132","n":1}]}],"resolved":true}},
  {"id":950042,"chap":"LudicrousVoltage","chapcn":"第6阶-荒唐电压(LuV)","chapi":9,"name":"物质操纵者 MKII","pre":[1680,1493],"desc":"MKII版本是物质操纵者系列中次顶级的升级型号。这一型号更加强大，其能量存储是上一代的10倍，方块作用范围达128格，并且放置速度达到每秒256个方块。\n\n除了具备MKI的全部功能外，你现在还可使用两种强大的新模式：\n\n- 复制/粘贴模式：选择一片区域，复制其中的方块，并可根据需要多次粘贴。与GT和AE2兼容性最佳。\n\n- 移动模式：与复制/粘贴类似，但会物理上的迁移已放置的方块。\n\n以下是一份可由物质操纵者复制/移动的内容简表，更完整的列表请参阅Readme文档，但此表应能让你大致了解它的功能之多。\n格雷科技：\n\n- 管道/线缆连接\n- 机器颜色\n- 机器朝向与输出方向\n- 基础机器设置（自动输出等）\n- 仓室设置（排序、堆叠限制等）\n- 多方块机器设置（溢出保护、批处理模式等）\n- 多方块结构旋转\n- 覆盖板\n- 强红石信号输出\n- 自定义名称\n- 虚拟电路\n- 总线/仓室的物品/流体锁定\n- 模式（适用于使用新式模式系统的机器）\n- 闪存数据\n- TecTech机器输入参数\n- ME输出总线/仓室容量\nAE2：\n\n- 颜色设置\n- 朝向\n- 配置\n- 升级组件\n- 自定义名称\n- 存储元件（将自动配置元件并安装其升级）\n- 任何样板（包括编码样板，但是空白样板不行）\n- 优先级设置\n- P2P设置\n- 矿物辞典/常规过滤器","items":[["matter-manipulator:itemMatterManipulator2",0,1]],"rule":{"pre":[1680,1493],"preLogic":"AND","taskLogic":"AND","groups":[{"id":"0:10","type":"retrieval","ignoreNBT":true,"partialNBT":true,"optional":true,"items":[{"k":"matter-manipulator:metaitem@15","n":1},{"k":"matter-manipulator:metaitem@13","n":1},{"k":"matter-manipulator:metaitem@12","n":1},{"k":"matter-manipulator:metaitem@11","n":1},{"k":"matter-manipulator:metaitem@14","n":1},{"k":"matter-manipulator:metaitem@21","n":1}]},{"id":"1:10","type":"retrieval","ignoreNBT":true,"partialNBT":true,"items":[{"k":"matter-manipulator:itemMatterManipulator2@0","n":1,"nbt":{"charge":1000000000,"config":{"blockSelectMode":"ALL","cables":{"b":"true","id":0,"m":0},"placeMode":"GEOMETRY","removeMode":"ALL","shape":"LINE"},"dv":0,"installedUpgrades":{},"jv":0,"upgradeProvidedCapabilities":0}}]}],"resolved":true}},
  {"id":950043,"chap":"LudicrousVoltage","chapcn":"第6阶-荒唐电压(LuV)","chapi":9,"name":"顽固胶水","pre":[1493],"desc":"氰基丙烯酸乙酯，俗称502胶水，是最好的胶水。但是强度越高……也越复杂。你现在不需要它，未来几个阶段可能也不需要，但它会让你的配方更有效率，并且在后期是必需的。\n\n严格来说这条产线在IV即可搭建，但并非必须；要展示一下你的真本领的话，就自己去NEI搜索配方吧！","items":[["miscutils:itemCellEthylCyanoacrylateSuperGlue",0,8]],"rule":{"pre":[1493],"preLogic":"AND","taskLogic":"AND","groups":[{"id":"0:10","type":"retrieval","ignoreNBT":true,"partialNBT":true,"items":[{"k":"miscutils:itemCellEthylCyanoacrylateSuperGlue@0","n":8}]}],"resolved":true}},
  {"id":950045,"chap":"LudicrousVoltage","chapcn":"第6阶-荒唐电压(LuV)","chapi":9,"name":"接下来为您展现：下界合金处理线","pre":[2599],"desc":"你不会真以为LuV只需要做硅岩处理吧？如果是，那你可得做好准备应对下界合金处理线了！\n\n别慌，只要你能搞懂小型加工循环和概率产出机制，这条生产线其实还算直接。还好，你有一本任务书，能引导你完成初始准备。\n\n注意-你需要先获取一级净化水和硅岩线圈才能做出完整的下界合金处理线。\n\n本任务线将从你必须准备的三样核心物品开始，它们是开启后续流程的前提：\n\n- 研磨地狱岩\n- 下界空气\n- 一些远古残骸\n\n这三样物品中的至少一样、很可能是两样，都需要你前往下界获取，所以务必确保你的装备准备妥当！\n\n若你已自行搭建完生产线，且不想完成单个子任务，可在完成本任务后，手持以下任意一项物品即可跳过子任务：\n\n- 1x 致密下界合金板\n- 64x 强键合下界合金纳米颗粒\n- 16x 下界合金锭","items":[],"rule":{"pre":[2599],"preLogic":"AND","taskLogic":"AND","groups":[{"id":"0:10","type":"checkbox","ignoreNBT":false,"partialNBT":false,"items":[]}],"resolved":true}},
  {"id":950046,"chap":"LudicrousVoltage","chapcn":"第6阶-荒唐电压(LuV)","chapi":9,"name":"下界空气和半流质下界空气","pre":[950045],"desc":"你是否曾在漫游下界时深吸一口气，却感到头晕目眩？事实上这是剧毒的空气导致的。或许我们的肺已经无可救药，但至少我们还可以利用这里浓密的空气来帮助我们的材料获取！\n\n若是你还没有利用起下界空气的含硫性质（说的就是你，硝基苯神教教徒），你现在就需要利用它了：用于制造半流质下界空气。\n\n在下界的产线画布放置进气仓，将收集到的下界空气送入真空冷冻机，制成半流质下界空气。","items":[["gregtech:gt.metaitem.01",30119,100]],"rule":{"pre":[950045],"preLogic":"AND","taskLogic":"AND","groups":[{"id":"0:10","type":"retrieval","ignoreNBT":true,"partialNBT":true,"optional":true,"items":[{"k":"gregtech:gt.blockmachines@861","n":1},{"k":"gregtech:gt.metaitem.01@30118","n":1000}]},{"id":"1:10","type":"retrieval","ignoreNBT":true,"partialNBT":true,"items":[{"k":"gregtech:gt.metaitem.01@30119","n":100}]}],"resolved":true}},
  {"id":950047,"chap":"LudicrousVoltage","chapcn":"第6阶-荒唐电压(LuV)","chapi":9,"name":"下界合金碎片","pre":[950045],"desc":"下界合金碎片是你下界合金生产线不可或缺的一部分，幸运的是你不需要很多。理论上，仅仅两片下界合金碎片便可满足冷热之间的自循环，（不过准备更多的碎片会提升你的生产效率）。\n\n你可以通过熔炼或使用锻造锤处理远古残骸来获得下界合金碎片，不过考虑到使用锻造锤有25%%的概率可以额外获得一个碎片，选择第一种方式的你一定有点大病。\n\n在世界页打开下界荒野，选择「寻找远古残骸」。","items":[["etfuturum:netherite_scrap",0,2]],"rule":{"pre":[950045],"preLogic":"AND","taskLogic":"AND","groups":[{"id":"0:10","type":"retrieval","ignoreNBT":true,"partialNBT":true,"optional":true,"items":[{"k":"etfuturum:ancient_debris@0","n":1}]},{"id":"1:10","type":"retrieval","ignoreNBT":true,"partialNBT":true,"items":[{"k":"etfuturum:netherite_scrap@0","n":2}]}],"resolved":true}},
  {"id":950048,"chap":"LudicrousVoltage","chapcn":"第6阶-荒唐电压(LuV)","chapi":9,"name":"下界合金材料","pre":[1212],"desc":"完成下界合金产线并成功搭建了Mk1聚变反应堆后，你终于可以获取硼等离子体了。它是各种下界合金材料所需的原料。\n\n这些材料在接下来的游戏中非常重要，并且会被广泛用于各种物品和材料。因此，在你继续推进进度时，升级产线的电力分配和所用配方非常重要。\n\n在产线升级方面，UHV级电力和量子操纵者是最重要的里程碑。\n\n你必须使用工业（等离子体）电弧炉。常规电弧炉是不够用的。","items":[["gregtech:gt.metaitem.01",11132,1]],"rule":{"pre":[1212],"preLogic":"AND","taskLogic":"AND","groups":[{"id":"0:10","type":"retrieval","ignoreNBT":true,"partialNBT":true,"optional":true,"items":[{"k":"gregtech:gt.metaitem.01@11323","n":1},{"k":"gregtech:gt.metaitem.03@32246","n":1},{"k":"gregtech:gt.metaitem.01@31009","n":1}]},{"id":"1:10","type":"retrieval","ignoreNBT":true,"partialNBT":true,"items":[{"k":"gregtech:gt.metaitem.01@11132","n":1}]}],"resolved":true}},
  {"id":950061,"chap":"LudicrousVoltage","chapcn":"第6阶-荒唐电压(LuV)","chapi":9,"name":"工业纯净水净化","pre":[2599],"desc":"一直以来,您都可以单单使用机器直接切割和雕刻硅电路晶圆.但是,这会导致最终晶圆出现严重缺陷,当您要生产更先进的电路时,就不能再容忍这种缺陷了.\n\n在具备了制造LuV元件的能力之后,您就可以制造净水厂了.这个多方块可以制造净化水,这将有助于制造更纯净和更完美的晶圆.对于您当前使用的硅岩掺杂晶圆来说,这还不是必需的,但使用净化水可以大大加快制作过程,因此绝对值得一试.\n\n净水厂本身并不运行配方,而是为您的净化水产线提供核心物流管理服务.您可以在净水厂周围建造与它相连的净水单元.净水厂为不同的净水单元提供电力和维护,并同步它们的配方周期.","items":[["gregtech:gt.blockmachines",9402,1]],"rule":{"pre":[2599],"preLogic":"AND","taskLogic":"AND","groups":[{"id":"0:10","type":"retrieval","ignoreNBT":true,"partialNBT":true,"items":[{"k":"gregtech:gt.blockmachines@9402","n":1}]},{"id":"1:10","type":"retrieval","ignoreNBT":true,"partialNBT":true,"optional":true,"items":[{"k":"gregtech:gt.blockcasings9@4","n":77},{"k":"gregtech:gt.blockcasings9@5","n":71},{"k":"gregtech:gt.blockcasings9@3","n":56},{"k":"gregtech:gt.blockframes@81","n":30}]}],"resolved":true}},
  {"id":950062,"chap":"LudicrousVoltage","chapcn":"第6阶-荒唐电压(LuV)","chapi":9,"name":"澄清器","pre":[950061],"desc":"水净化过程的第一步是澄清器.操作这台机器非常简单,您只需为过滤器保持稳定的活性炭供应.使用这台机器,您就能制造出1级净化水,从而将硅岩掺杂的单晶硅和晶圆的加工速度提高25%%.","items":[["gregtech:gt.blockmachines",9403,1]],"rule":{"pre":[950061],"preLogic":"AND","taskLogic":"AND","groups":[{"id":"0:10","type":"retrieval","ignoreNBT":true,"partialNBT":true,"items":[{"k":"gregtech:gt.blockmachines@9403","n":1}]},{"id":"1:10","type":"retrieval","ignoreNBT":true,"partialNBT":true,"optional":true,"items":[{"k":"gregtech:gt.blockcasings9@5","n":123},{"k":"gregtech:gt.blockcasings3@11","n":21},{"k":"gregtech:gt.blockframes@84","n":12},{"k":"gregtech:gt.blockframes@335","n":12},{"k":"gregtech:gt.blockcasings8@1","n":3}]}],"resolved":true}},
  {"id":950063,"chap":"LudicrousVoltage","chapcn":"第6阶-荒唐电压(LuV)","chapi":9,"name":"臭氧化","pre":[950062],"desc":"想要更快地处理晶圆?通过使用臭氧法制造的2级净化水,您现在可以将加工时间缩短50%%.要运行这台机器,你需要用强激光轰击空气来制造大量臭氧气体.为了加快这一过程,你需要制作高强度激光蚀刻机(如果你还没有准备好).\n\n这个多方块机器对臭氧输入仓的位置非常挑剔.如果你不知道为什么机器没有成型,很可能是你忘记把这个仓室放在正确的位置上了.使用全息投影仪查看它的正确位置.","items":[["gregtech:gt.blockmachines",9404,1]],"rule":{"pre":[950062],"preLogic":"AND","taskLogic":"AND","groups":[{"id":"0:10","type":"retrieval","ignoreNBT":true,"partialNBT":true,"items":[{"k":"gregtech:gt.blockmachines@9404","n":1}]},{"id":"1:10","type":"retrieval","ignoreNBT":true,"partialNBT":true,"optional":true,"items":[{"k":"gregtech:gt.blockcasings9@10","n":96},{"k":"gregtech:gt.blockcasings9@9","n":27},{"k":"gregtech:gt.blockframes@316","n":6},{"k":"gregtech:gt.blockcasings8@1","n":3}]}],"resolved":true}},
  {"id":2601,"name":"电路装配线","chap":"MassProcessing","chapcn":"大规模加工","chapi":23,"pre":[1680,1493,1683,1412,2606],"desc":"这些用于构建4台7片的电路装配线,足够满足一个系列的电路板制造. 如果你仅需要某个系列中的一种电路板(比如微处理器),那就把它除以4.\n\n假设你在LuV任务栏已经获得了所需的压印电路,现在就可以开始制造晶体系列的电路装配线了. 我们一上来就要求4台是因为每台电路装配线只能铭刻一次,无法移除铭刻.是的,你想用电路装配线制造的每种电路板都需要一台专用电路装配线.\n\n作为装配线,它与普通装配线的工作方式一致,每个总线按顺序提供原料,但由于是单台专用,所以用起来就容易多了,同时高阶合成表也便宜多了.\n\n电路装配线的原料是封装的,所以一次可以制造16个电路板(ULV和LV电路更多),节约时间、EU还有焊锡(或铋铅合金).在组装机中配合聚乙烯可以制造封装元件.\n\n[note]顺便一提,你可以选择安装更高级的仓/总线,不过合成时的原料顺序还是得与NEI一致.另外,电路装配线可以无损超频.[/note]","items":[],"rule":{"pre":[1680,1493,1683,1412,2606],"preLogic":"AND","taskLogic":"AND","groups":[{"id":"0:10","type":"retrieval","ignoreNBT":true,"partialNBT":true,"optional":true,"items":[{"k":"gregtech:gt.blockcasings3@10","n":76},{"k":"gregtech:gt.blockcasings2@5","n":28},{"k":"gregtech:gt.blockglass1@0","n":56},{"k":"gregtech:gt.blockcasings2@0","n":52},{"k":"gregtech:gt.blockmachines@70","n":24},{"k":"gregtech:gt.blockmachines@80","n":4},{"k":"gregtech:gt.blockmachines@51","n":4},{"k":"gregtech:gt.blockmachines@90","n":4},{"k":"gregtech:gt.blockmachines@46","n":4}]},{"id":"1:10","type":"retrieval","ignoreNBT":true,"partialNBT":true,"items":[{"k":"gregtech:gt.blockmachines@12735","n":4}]}],"resolved":true}}
